'use strict';
const A=window.Analytics,D=window.MARKETLAB_DATA,$=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>n==null?'—':Number(n).toLocaleString('en-US'),pct=(n,d=1)=>n==null?'—':(n*100).toFixed(d)+'%',dec=(n,d=3)=>n==null?'—':Number(n).toFixed(d),cents=n=>n==null?'—':(n>=0?'+':'')+(n*100).toFixed(2)+'¢',date=s=>s?new Date(s).toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'}):'—';
const nav=[['Research',[['overview','Overview'],['market','Market Explorer'],['calibration','Calibration Lab'],['edge','Edge Analyzer'],['validation','Validation Lab']]],['System',[['history','Historical Universe'],['execution','Execution Modeling'],['failure','Failure Analysis'],['settlement','Settlement & Reconciliation'],['experiments','Experiment Registry']]],['Project',[['architecture','System Architecture'],['methodology','Methodology'],['timeline','Project History'],['about','About']]]];
const titles=Object.fromEntries(nav.flatMap(([,items])=>items));
const state={page:'overview',period:'all',start:'',end:'',query:'',side:'all',feature:'probability',secondary:'session',bins:10,pageIndex:0,fee:1,slippage:1,fill:90};
let experiments=[];try{experiments=JSON.parse(localStorage.getItem('marketlab-experiments-v1')||'[]');if(!Array.isArray(experiments))experiments=[];experiments=experiments.slice(0,100);}catch{experiments=[];}
const tag=(t,c='')=>`<span class="pill ${c}">${esc(t)}</span>`;
const button=(t,a,c='')=>`<button class="button ${c}" data-action="${a}">${t}</button>`;
const body=s=>`<div class="panel-body">${s}</div>`;
const legend=()=>'<div class="legend"><span><i class="dot"></i>Research</span><span><i class="dot teal"></i>Later test</span></div>';
function heading(title,sub,actions=''){return `<div class="page-heading"><div><p class="eyebrow">Research workspace / ${D.kind==='synthetic'?'Demonstration':'Imported sample'}</p><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${actions}</div></div>`;}
function notice(){return `<div class="notice"><span><strong>${D.kind==='synthetic'?'Synthetic dataset.':'Imported sample.'}</strong> ${D.kind==='synthetic'?'All charts use fictional, seeded observations. These are not KLEM research results.':esc(D.sampling)}</span><a href="#methodology">View provenance ↗</a></div>`;}
function metric(label,value,detail,code=''){return `<div class="metric"><div class="metric-label">${label}<span class="metric-code">${code}</span></div><div class="metric-value">${value}</div><small>${detail}</small></div>`;}
function panel(title,sub,content,foot='',right=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${right}</div>${content}${foot?`<div class="panel-foot">${foot}</div>`:''}</section>`;}
function table(headers,rows,wrap=false){return `<div class="table-wrap ${wrap?'wrap':''}"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
const empty=(t='No observations match these filters.')=>`<div class="empty"><strong>No data to evaluate</strong><p>${t}</p>${button('Reset filters','reset')}</div>`;
function rows(){return D.rows.filter(r=>(state.period==='all'||r.period===state.period)&&(!state.start||r.timestamp.slice(0,10)>=state.start)&&(!state.end||r.timestamp.slice(0,10)<=state.end)&&(state.side==='all'||r.side===state.side)&&(!state.query||r.ticker.toLowerCase().includes(state.query.toLowerCase())));}
function select(id,label,options,value){return `<div class="field"><label for="${id}">${label}</label><select id="${id}" data-state="${id}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`;}
function filters(extra=''){return `<div class="filters">${select('period','Evaluation period',[['all','Research + test'],['research','Research'],['test','Later test']],state.period)}<div class="field"><label for="start">From (UTC)</label><input id="start" data-state="start" type="date" value="${esc(state.start)}"></div><div class="field"><label for="end">Through (UTC)</label><input id="end" data-state="end" type="date" value="${esc(state.end)}"></div>${select('side','Selected side',[['all','Both sides'],['YES','YES'],['NO','NO']],state.side)}${extra}${button('Reset','reset','small')}</div>`;}
const features=()=>Object.entries(A.specs).map(([k,v])=>[k,v.label]);
function chart(sample,bins=10){if(!sample.length)return empty();const W=620,H=275,L=48,R=20,T=22,B=40,x=p=>L+p*(W-L-R),y=p=>H-B-p*(H-T-B);let out=`<svg class="chart" role="img" aria-label="YES probability versus observed YES rate; bars show 95 percent Wilson intervals" viewBox="0 0 ${W} ${H}">`;for(let i=0;i<=5;i++){let p=i/5;out+=`<path d="M${L} ${y(p)}H${W-R}" stroke="#edf0f2"/><text x="${L-10}" y="${y(p)+3}" text-anchor="end">${i*20}%</text><text x="${x(p)}" y="${H-21}" text-anchor="middle">${i*20}%</text>`;}out+=`<path d="M${x(0)} ${y(0)}L${x(1)} ${y(1)}" stroke="#c8d0d7" stroke-dasharray="5 5"/><text x="${W/2}" y="${H-2}" text-anchor="middle">Quoted YES probability</text>`;for(const period of ['research','test']){const c=period==='research'?'#d8542e':'#357f80',points=A.calibration(sample.filter(r=>r.period===period),bins);out+=`<polyline points="${points.map(p=>`${x(p.expected)},${y(p.observed)}`).join(' ')}" fill="none" stroke="${c}" stroke-width="2"/>`;for(const p of points){const xx=x(p.expected);out+=`<g><title>${period}: expected ${pct(p.expected)}, observed ${pct(p.observed)}, n=${p.n}; 95% CI ${pct(p.ci[0])}–${pct(p.ci[1])}</title><path d="M${xx} ${y(p.ci[0])}V${y(p.ci[1])}" stroke="${c}" opacity=".3"/><circle cx="${xx}" cy="${y(p.observed)}" r="${p.n<30?3:4}" fill="white" stroke="${c}" stroke-width="2"/></g>`;}}return out+'</svg>';}
function split(){const a=D.periods.research.n,b=D.periods.test.n,total=a+b;return body(`<div class="split-top"><div><strong>${total?pct(a/total,0):'—'} / ${total?pct(b/total,0):'—'}</strong><br><small>Chronological split · canonical markets</small></div>${tag('Fixed cutoff','research')}</div><div class="split-track"><span style="width:${total?a/total*100:0}%"></span></div><div class="split-labels"><div><span class="dot"></span> Research<strong>${num(a)}</strong><small>${date(D.rows[0]?.timestamp)} → ${date(D.rows.filter(r=>r.period==='research').at(-1)?.timestamp)}</small></div><div><span class="dot teal"></span> Later test<strong>${num(b)}</strong><small>${date(D.validation.cutoff)} → ${date(D.rows.at(-1)?.timestamp)}</small></div></div><div class="rule"></div><div class="check-row"><span>Ticker overlap</span><b>0 shared tickers</b></div><div class="check-row"><span>Labels crossing cutoff</span><b>${D.validation.purged} purged</b></div><div class="check-row"><span>Sample unit</span><span>One market</span></div>`);}
function pipeline(){return `<div class="pipeline">${[['Signal','Decision-time features'],['Order','Hypothetical instruction'],['Fill','Cost & fill assumptions'],['Settlement','Official YES outcome'],['Attribution','Reconciled event record']].map(([t,s],i)=>`<div class="stage"><div class="stage-number">0${i+1}</div><strong>${t}</strong><p>${s}</p></div>`).join('')}</div>`;}
const featureRows=(sample,key)=>A.groups(sample,key).map(g=>[esc(g.label),num(g.research.n),cents(g.research.mean_return),num(g.test.n),cents(g.test.mean_return),tag(g.status,g.status==='Direction changed'?'bad':g.status==='Needs more data'?'warn':'')]);
const audit=(items)=>items.map(([a,b])=>`<div class="audit"><span>${a}</span><strong>${b}</strong></div>`).join('');
function overview(){const sample=rows(),s=A.summary(sample);return heading('Research, with a higher standard.','From market observations to evidence that survives later evaluation.',`<a href="#market" class="button">Explore markets ↗</a>${button('Export sample ↓','export','primary')}`)+notice()+`<div class="metrics">${metric('Markets in current sample',num(s.n),'One decision observation per ticker','N')}${metric('Research sample',num(D.periods.research.n),'Earlier chronological observations','01')}${metric('Later test sample',num(D.periods.test.n),'Separated at a fixed time boundary','02')}${metric('Probability accuracy',dec(s.brier),'Brier score · lower is better','BS')}</div><div class="grid-2">${panel('Does probability match reality?','Calibration across research and later test markets',body(chart(sample)),`<span>95% Wilson intervals · not search-adjusted</span><a href="#calibration" class="text-link">Open calibration lab ↗</a>`,legend())}${panel('Built around later data','Evaluation discipline starts at the dataset boundary',split(),'<a href="#validation" class="text-link">Inspect validation design ↗</a>')}</div>${panel('The lifecycle behind the research','Conceptual KLEM lifecycle · this build models costs and reconciles example events',pipeline(),'<span>RESEARCH → BACKTEST → PAPER → SHADOW → LIVE are documented modes; no live execution is included.</span>')}<div class="grid-2">${panel('An attractive result is only the beginning.','Feature relationships across time',table(['YES probability','Research n','Mean return','Test n','Mean return','Evidence'],featureRows(D.rows,'probability')),`<span>Gross return per $1 contract. No feature is promoted from these comparisons.</span><a href="#edge" class="text-link">Explore ↗</a>`)}${panel('Evidence, not a performance pitch','An inspectable view of the research process',body(audit([['Source data',D.kind==='synthetic'?'Synthetic fixture':'Imported sample'],['Real KLEM performance claims','Awaiting source reports'],['Public/private boundary','Allowlisted fields'],['Decision-time feature registry','8 fields']])+'<div class="rule"></div><div class="callout">A relationship becomes useful evidence only after it survives stricter evaluation on later, unseen data.</div>'))}</div>`;}
function market(){const sample=rows(),size=15,pages=Math.max(1,Math.ceil(sample.length/size));state.pageIndex=Math.min(state.pageIndex,pages-1);const shown=sample.slice(state.pageIndex*size,(state.pageIndex+1)*size);return heading('Market Explorer','Inspect the canonical observation behind each result. Outcomes are settlement labels.',button('Export filtered CSV ↓','export','primary'))+notice()+filters(`<div class="field"><label for="query">Ticker contains</label><input id="query" data-state="query" value="${esc(state.query)}" placeholder="Search ticker"></div>`)+panel('Observation ledger',`${num(sample.length)} matching markets · times in UTC`,sample.length?table(['Market','Decision time','Side','YES prob.','TTX','ATR','YES outcome','Period',''],shown.map(r=>[`<span class="mono">${esc(r.ticker)}</span>`,esc(r.timestamp.slice(0,16).replace('T',' ')),tag(r.side),pct(r.probability),r.ttx_minutes+'m',dec(r.atr,1),r.outcome,tag(r.period,r.period),`<button class="row-button" data-detail="${esc(r.ticker)}">Inspect ↗</button>`]))+`<div class="pager"><span>Page ${state.pageIndex+1} / ${pages}</span><div class="actions"><button class="button small" data-action="prev" ${!state.pageIndex?'disabled':''}>← Previous</button><button class="button small" data-action="next" ${state.pageIndex===pages-1?'disabled':''}>Next →</button></div></div>`:empty(),'<span>Earliest valid observation per ticker. Historical paths are unavailable in this public sample.</span>');}
function calibration(){const sample=rows(),b=A.calibration(sample,state.bins),s=A.summary(sample);return heading('Calibration Lab','Compare quoted YES probabilities with official YES outcome frequencies.')+notice()+filters(select('bins','Probability buckets',[[5,'5 buckets'],[10,'10 buckets'],[20,'20 buckets']],state.bins))+`<div class="metrics">${metric('Markets evaluated',num(sample.length),'Unique canonical tickers','N')}${metric('Brier score',dec(s.brier),'Mean squared probability error','BS')}${metric('Populated buckets',num(b.length),`Of ${state.bins} equal-width buckets`,'BIN')}${metric('Small-sample buckets',num(b.filter(r=>r.n<30).length),'Fewer than 30 observations','n < 30')}</div>`+panel('Calibration by evaluation period','Horizontal: quoted YES probability · vertical: observed YES frequency',body(chart(sample,state.bins)),'<span>Dashed line = perfect calibration. Wilson intervals assume independent outcomes; serial dependence may widen uncertainty.</span>',legend())+panel('Bucket evidence','Periods pooled unless a single period is selected',sample.length?table(['Probability bucket','n','Expected YES','Observed YES','Gap','95% Wilson interval','Sample'],b.map(r=>[`${pct(r.low,0)}–${pct(r.high,0)}`,r.n,pct(r.expected),pct(r.observed),pct(r.observed-r.expected),`${pct(r.ci[0])}–${pct(r.ci[1])}`,tag(r.n<30?'Needs more data':'Descriptive sample',r.n<30?'warn':'')])):empty());}
function bars(entries,color=''){const max=Math.max(1,...entries.map(e=>e.value));return `<div class="bar-list">${entries.map(e=>`<div class="bar-item"><span>${esc(e.label)}</span><div class="bar-bg"><div class="bar-fill ${color}" style="width:${e.value/max*100}%"></div></div><span class="number">${num(e.value)}</span></div>`).join('')}</div>`;}
function histogram(sample){const bins=Array.from({length:10},(_,i)=>({low:-1+i*.2,n:0}));for(const r of sample){const[p,w]=A.trade(r);bins[Math.min(9,Math.max(0,Math.floor((w-p+1)/.2)))].n++;}return bars(bins.map(b=>({label:`${Math.round(b.low*100)} to ${Math.round((b.low+.2)*100)}¢`,value:b.n})));}
function edge(){const sample=rows(),s=A.summary(sample),groups=A.groups(sample,state.feature),secondary=[...new Set(sample.map(r=>A.bucket(r,state.secondary)))];return heading('Edge Analyzer','Investigate relationships. Separate exploration from confirmation.',button('Save exploration','save-experiment','primary'))+notice()+filters(select('feature','Primary feature',features(),state.feature)+select('secondary','Compare with',features(),state.secondary))+panel('Persistence across periods','Preset buckets; gross selected-side return per $1 contract',sample.length?table([esc(A.specs[state.feature].label),'Research n','Research mean','Test n','Test mean','Status'],featureRows(sample,state.feature)):empty(),'<span>30 markets per period is a display threshold, not statistical proof. Matching directions do not establish persistence.</span>')+`<div class="grid-equal">${panel('Return distribution','Gross return per selected-side contract',body(sample.length?histogram(sample):empty()))}${panel('Descriptive statistics','All matching observations',body(table(['Statistic','Value'],[['Sample count',num(s.n)],['Mean return',cents(s.mean_return)],['Median return',cents(s.median_return)],['Selected-side win rate',pct(s.win_rate)],['Coverage',`${date(sample[0]?.timestamp)} – ${date(sample.at(-1)?.timestamp)}`]])),'<span>Returns assume entry at the quoted side probability, before fees and slippage.</span>')}</div>`+panel('Pairwise inspection',`${esc(A.specs[state.feature].label)} × ${esc(A.specs[state.secondary].label)} · gross mean return and n`,sample.length?table([esc(A.specs[state.feature].label),...secondary.map(esc)],groups.map(g=>[esc(g.label),...secondary.map(v=>{const s=A.summary(g.rows.filter(r=>A.bucket(r,state.secondary)===v));return `<div class="heat-cell">${cents(s.mean_return)}<br><span class="tiny muted">n = ${s.n}</span></div>`;})])):empty(),'<span>Pairwise searches are exploratory and multiply the opportunity for false discoveries.</span>');}
function validation(){const v=D.validation,a=D.periods.research,b=D.periods.test,ci=v.bootstrap.ci;return heading('Validation Lab','Full compiled dataset. Explorer filters do not change the fixed evaluation design.')+notice()+`<div class="grid-equal">${panel('Time is the boundary','Earliest observation per ticker; settlement-aware purge',split())}${panel('What changed on later data?','Descriptive comparison; no fitted strategy or claimed alpha',body(table(['Measure','Research','Later test','Difference'],[['Markets',num(a.n),num(b.n),'—'],['Brier score',dec(a.brier),dec(b.brier),a.brier==null||b.brier==null?'—':dec(b.brier-a.brier)],['Mean gross return',cents(a.mean_return),cents(b.mean_return),a.mean_return==null||b.mean_return==null?'—':cents(b.mean_return-a.mean_return)],['Win rate',pct(a.win_rate),pct(b.win_rate),a.win_rate==null||b.win_rate==null?'—':pct(b.win_rate-a.win_rate)]])))}</div>`+panel('Expanding-window evaluation','Four chronological folds; training labels must settle before each test window',table(['Fold','Test coverage','Research n','Test n','Research mean','Test mean'],v.folds.map(f=>[tag('F'+f.fold),`${date(f.start)} – ${date(f.end)}`,f.research.n,f.test.n,cents(f.research.mean_return),cents(f.test.mean_return)])),'<span>Temporal diagnostics of a fixed observation rule. These folds do not fit, tune or select a strategy.</span>')+`<div class="grid-equal">${panel('Moving-block bootstrap','Later test sample · gross mean return uncertainty',body(`<div class="two-stat"><div><small>95% percentile interval</small><strong>${ci?`${cents(ci[0])} → ${cents(ci[1])}`:'Unavailable'}</strong></div></div>${audit([['Resamples',num(v.bootstrap.repetitions)],['Contiguous markets per block',num(v.bootstrap.block_size)],['Random seed',num(v.bootstrap.seed)]])}<div class="rule"></div><p class="small muted">Conditional on this sample and block length. Not corrected for multiple testing, regime shifts or prior strategy selection.</p>`))}${panel('Sensitivity to execution costs','Later test sample · 100% fill assumption',body(table(['Fee + slippage / fill','Gross mean','Net / attempt'],[0,1,2,3,5].map(cost=>[cost+'¢',cents(b.mean_return),cents(A.execution(D.rows.filter(r=>r.period==='test'),cost,0,1).mean_net)]))),'<span>Illustrative constant costs, not exchange fee schedules.</span>')}</div><div class="callout">Freeze rules before observing final test labels. Browsing these results makes this a retrospective diagnostic; a new untouched window is required for future confirmation.</div>`;}
function claims(){return table(['Dataset','Claim','User-provided value','Evidence'],D.claims.map(c=>[esc(c.dataset),esc(c.metric),esc(c.value),`${tag('Unverified','warn')}<br><span class="tiny">${esc(c.evidence)}</span>`]),true);}
function arch(columns){return `<div class="architecture">${columns.map(([label,cards])=>`<div class="arch-column"><div class="arch-title">${label}</div>${cards.map(([name,desc],i)=>`<div class="arch-card ${i===0?'accent':''}"><strong>${name}</strong><small>${desc}</small></div>`).join('')}</div>`).join('')}</div>`;}
function history(){return heading('Historical Universe','Reconstruct observations while preserving a clear boundary between evidence and planned integration.')+notice()+panel('From archive to research sample','Implemented public import path',arch([['01 / INGEST',[['Local CSV or JSONL','Streaming flat records'],['Explicit field mapping','No unit inference']]],['02 / VALIDATE',[['Strict public schema','Timezone, outcome and bounds'],['SQLite event store','Deduplicate on disk']]],['03 / COMPILE',[['Canonical markets','One observation per ticker'],['Public sample','Evenly spaced over time']]]]),'<span>Exchange discovery, reference-price retrieval and historical path reconstruction are documented KLEM concepts; their source code was not provided.</span>')+`<div class="grid-equal">${panel('Current public coverage','Only the compiled sample is available in this workstation',body(audit([['Compiled markets',num(D.rows.length)],['Earliest decision',esc(D.rows[0]?.timestamp.slice(0,10))],['Latest decision',esc(D.rows.at(-1)?.timestamp.slice(0,10))],['Source archive tickers',D.source_tickers?num(D.source_tickers):'Not supplied'],['Historical observation paths','Not supplied']])))}${panel('Reduced search vs. exhaustive history','Comparator evidence required',body('<div class="callout">The brief describes a reduced-search validation experiment. Its report was not attached, so this release does not claim equivalence or display its figures as verified results.</div><div class="rule"></div><p class="small muted">Verification requires candidate event IDs, decision timestamps, missing-path counts and coverage against the exhaustive reference, together with a report hash and search configuration.</p>'))}</div>`+panel('Research figure register','User-provided claims retained for future source verification',claims());}
function executionResults(v){return `<div class="two-stat"><div><small>Gross / attempt</small><strong>${cents(v.attempts?v.gross/v.attempts:null)}</strong></div><div><small>Net / attempt</small><strong>${cents(v.mean_net)}</strong></div></div><div class="rule"></div>${audit([['Attempted contracts',num(v.attempts)],['Price-eligible contracts',num(v.eligible)],['Expected filled contracts',dec(v.expected_fills,1)],['Expected net dollars','$'+dec(v.net,2)]])}<p class="chart-notes">Expected values, not realized trades. One contract per observation.</p>`;}
function execution(){return heading('Execution Modeling','Inspect how costs and partial participation change hypothetical signal outcomes.')+notice()+filters()+`<div class="grid-equal">${panel('Scenario assumptions','Illustrative inputs; not exchange-specific fees',body([['fee','Fee per filled contract',0,10,.25,'¢'],['slippage','Adverse entry slippage',0,10,.25,'¢'],['fill','Expected fill rate',0,100,5,'%']].map(([id,label,min,max,step,unit])=>`<div class="range-row"><label for="${id}">${label}<output id="${id}-value">${state[id]}${unit}</output></label><input type="range" id="${id}" data-scenario="${id}" min="${min}" max="${max}" step="${step}" value="${state[id]}"></div>`).join('')+'<div class="callout">Fill probability is assumed independent of outcome. Latency, queue priority and adverse selection require timestamped quotes and fill logs; they are not simulated here.</div>'))}${panel('The cost of implementation','Per attempted $1 selected-side contract',body(`<div id="scenario-results">${executionResults(A.execution(rows(),state.fee,state.slippage,state.fill/100))}</div>`))}</div>`+panel('Signal → order → fill → settlement → attribution','Conceptual lifecycle with no live order controls',pipeline(),'<span>Orders whose slipped entry price reaches $1 are treated as unfillable. Fees apply only to expected fills.</span>');}
function failure(){const sample=rows(),losses=sample.filter(r=>!A.trade(r)[1]),streaks=A.lossStreaks(sample),groups=A.groups(sample,state.feature);return heading('Failure Analysis','Study the conditions around losses without claiming they predict future failures.')+notice()+filters(select('feature','Regime feature',features(),state.feature))+`<div class="metrics">${metric('Market outcomes',num(sample.length),'Current filtered sample','N')}${metric('Selected-side losses',num(losses.length),'Outcome differs from selected side','L')}${metric('Loss frequency',pct(sample.length?losses.length/sample.length:null),'Conditional on this sample','%')}${metric('Longest loss run',num(streaks.length?Math.max(...streaks.map(s=>s.length)):0),'In filtered chronological order','RUN')}</div><div class="grid-equal">${panel('Loss runs','Run lengths in the filtered sequence; gaps are ignored',body(streaks.length?bars(streaks.map(s=>({label:s.length+' losses',value:s.count}))):'<p class="small muted">No loss runs in this sample.</p>'))}${panel('Loss frequency by regime',esc(A.specs[state.feature].label),table(['Bucket','Research losses / n','Test losses / n','Difference'],groups.map(g=>{const a=g.rows.filter(r=>r.period==='research'),b=g.rows.filter(r=>r.period==='test'),la=a.filter(r=>!A.trade(r)[1]).length,lb=b.filter(r=>!A.trade(r)[1]).length;return [esc(g.label),`${la} / ${a.length}`,`${lb} / ${b.length}`,a.length&&b.length?pct(lb/b.length-la/a.length):'—'];})))}</div>`+panel('Failure-focused research protocol','The brief describes a reverse-loss study; its data and rules are unavailable.',body('<div class="prose"><h3>Separate discovery, tuning and final evaluation</h3><p>Discover regimes on early data, tune in a separate window, and evaluate frozen rules once on an untouched final period. This release has a two-way split and does not reproduce that three-stage KLEM study.</p><h3>Features must exist before the decision</h3><p>Loss streaks here are retrospective diagnostics, not entry features. A prior-result feature would require an as-of settlement join, not the previous row’s eventual outcome.</p></div>'));}
function settlement(){const sample=D.reconciliation;return heading('Settlement & Reconciliation','Make disagreement visible before attributing a result to an experiment.')+'<div class="notice"><span><strong>Fictional event fixtures.</strong> These demonstrate reconciliation checks regardless of the active research dataset.</span></div>'+`<div class="metrics">${metric('Event records',sample.length,'Includes a deliberate duplicate','N')}${metric('Matched',sample.filter(r=>r.status==='Matched').length,'Local and official outcomes agree','OK')}${metric('Mismatch',sample.filter(r=>r.status==='Mismatch').length,'Requires correction before attribution','!')}${metric('Other exceptions',sample.filter(r=>!['Matched','Mismatch'].includes(r.status)).length,'Missing, pending or duplicate','Q')}</div>`+panel('Reconciliation queue','Recorded YES outcome vs. official YES settlement',table(['Event','Market','Recorded YES','Official YES','Check'],sample.map(r=>[esc(r.event_id),`<span class="mono">${esc(r.ticker)}</span>`,r.recorded_outcome??'—',r.official_outcome??'Pending',tag(r.status,r.status==='Matched'?'test':r.status==='Mismatch'?'bad':'warn')])),'<span>Fixture statuses are computed in Python; these are not actual fills.</span>')+panel('Attribution after reconciliation','Public engineering example',body('<div class="prose"><p><strong>Identity first.</strong> Detect repeated event IDs before counting any result twice.</p><p><strong>Official outcome next.</strong> Keep pending settlements separate from wins and losses. Quarantine missing local state and disagreements.</p><p><strong>Attribute last.</strong> Join a reconciled event to its frozen experiment and actual fills. This release demonstrates checks; it does not connect to a settlement API or repair live state.</p></div>'));}
function registry(){return heading('Experiment Registry','Save reproducible exploration settings locally. Historical inspection is not prospective confirmation.',button('Save current exploration','save-experiment','primary'))+notice()+panel('Local exploration records','Stored in this browser only · export to retain or share',experiments.length?table(['ID','Feature','Sample','Period','Status',''],experiments.map((e,i)=>[esc(e.id),esc(e.feature),num(e.n),esc(e.period),tag('Exploratory','warn'),`<button class="row-button" data-experiment="${i}">Details ↗</button>`])):'<div class="empty"><strong>No saved explorations yet</strong><p>Choose a feature in Edge Analyzer, then save its filters, sample count and dataset hash.</p><a href="#edge" class="button">Open Edge Analyzer ↗</a></div>',`<span>No KLEM experiment outcomes have been imported.</span><div class="actions">${button('Export registry ↓','export-experiments','small')}${button('Clear local records','clear-experiments','small')}</div>`)+panel('Promotion requires evidence','A workflow specification, not automatically awarded status',body('<div class="prose"><p><strong>Exploratory:</strong> question and dataset identified. The browser creates this status only.</p><p><strong>Frozen:</strong> immutable configuration committed before future labels exist.</p><p><strong>Testing:</strong> later observations accumulate under the frozen configuration.</p><p><strong>Rejected / unstable:</strong> predefined persistence or quality criteria fail.</p><p><strong>Persisted out of sample:</strong> predefined criteria pass with sufficient independent evidence. This build assigns no such verdict from a favorable chart.</p></div>'));}
function architecture(){return heading('System Architecture','A lightweight public workstation backed by a reproducible Python research pipeline.')+panel('A deliberate public/private boundary','Cards describe shipped components. Broader KLEM integrations are documented below.',arch([['01 / Local private processing',[['CSV / JSONL archives','Kept outside the public repository'],['Streaming ingestion','Strict schema · explicit units · allowlist'],['SQLite observation store','Disk-backed deduplication · source hashes']]],['02 / Python analytical build',[['Canonical public sample','Earliest decision per market · time coverage'],['Validation engine','Chronology · label purge · block bootstrap'],['Static dataset compiler','Metrics · provenance · sample metadata']]],['03 / Public research product',[['Interactive workstation','Calibration · features · cost scenarios'],['Audit surfaces','Methodology · claims · reconciliation fixtures'],['GitHub Pages deployment','Static files · no credentials · no API server']]]]),'<span>Python compiles the artifact; JavaScript computes filtered views. No source archive or account state is sent to the browser.</span>')+panel('Broader KLEM lifecycle','From the supplied project brief',pipeline())+panel('Integration boundary','Documented, not implemented in this release',body('<div class="prose"><p>The brief describes Kalshi discovery, Bitcoin reference ingestion, historical replay, shadow monitoring, order construction and live settlement monitoring. Those implementations were not attached.</p><p>This repository supplies a public import contract and analytical product without claiming to reproduce private KLEM execution code.</p><p><strong>Modes:</strong> RESEARCH, BACKTEST, PAPER, SHADOW, LIVE. Only offline research and illustrative execution-cost modeling are implemented here.</p></div>'));}
function methodology(){return heading('Methodology & Provenance','Every number should have a dataset, an evaluation stage and an inspectable meaning.')+notice()+panel('Active dataset','The file behind this build',body(audit([['Dataset type',esc(D.kind)],['Public schema','Version '+D.schema_version],['Canonical markets',num(D.rows.length)]])+`<p class="tiny muted" style="margin-top:15px">SHA-256</p><div class="code-block mono">${esc(D.dataset_sha256)}</div><p class="small muted" style="margin-top:15px">${esc(D.sampling)}</p><a href="public-dataset.json" download class="button">Download public input JSON ↓</a>`))+`<div class="grid-equal">${panel('Decision-time features','Only these fields are selectable for feature exploration',body(`<div class="feature-grid">${Object.values(A.specs).map(s=>`<div class="feature-chip">${esc(s.label)}</div>`).join('')}</div><div class="rule"></div><p class="small muted">Outcome, realized returns, settlement result and “edge versus implied” are excluded. Source features still require an as-of audit; schema validation cannot prove they were calculated without future information.</p>`))}${panel('Definitions & assumptions','Interpret a metric before comparing it',body('<div class="prose"><p><strong>Probability:</strong> quoted YES probability, fraction 0–1.</p><p><strong>Outcome:</strong> official YES result, 0 or 1.</p><p><strong>Selected-side return:</strong> settlement payoff minus quoted side price per $1 contract, before costs.</p><p><strong>Brier score:</strong> mean of (YES probability − YES outcome)².</p><p><strong>Intervals:</strong> 95% Wilson for outcome rates; moving-block percentile bootstrap for chronological mean returns.</p></div>'))}</div>`+panel('Limits that change interpretation','Sampling, dependence, search and execution matter',body('<div class="prose"><ul><li>One observation per ticker avoids repeated rows pretending to be independent markets. Related markets may still be dependent.</li><li>Evenly spaced public exports preserve time coverage but are descriptive samples, not substitutes for full-universe inference.</li><li>Feature searches and pairwise comparisons are exploratory and not adjusted for multiple testing.</li><li>Quoted probability is a modeling price, not evidence an order could execute there.</li><li>ATR and momentum need source-specific definitions and units before comparison across imports.</li><li>Missing source reports prevent verification of the historical KLEM figures below.</li></ul></div>'))+panel('Unverified historical claims','These values never populate the application’s KPI cards',claims());}
function timeline(){const entries=[['Foundation','Research capture','klem_crypto15m_research · KLEM_RESEARCH_v4','Folder names indicate multiple iterations. Their contents were not supplied.'],['Universe','Historical reconstruction','klem2_historical_universe · klem2_targeted_event_history','The brief describes reconstruction and comparison against exhaustive retrieval.'],['Exploration','Universal Angle Lab','klem2_universal_angle_lab · klem15_dm10_angle_lab','The brief describes single-feature and combination searches, including rejection of leakage-prone features.'],['Evaluation','Forward validation','klem15_dm10_forward · klem15_v1_forward','Forward-related folder names are visible. No frozen configurations or results can be verified from names alone.'],['Diagnostics','Failure & regime analysis','klem_streak_fast_output · post5_regime_output','Failure analysis is described in the brief; its detector and output are unavailable.'],['This build','Public research workstation','marketlab/ · web/ · tests/','Shipped: streaming import, strict schema, chronological validation, interactive analytics and deployment workflow.']];return heading('Project History','A thematic map of the supplied evidence, not an invented release chronology.')+panel('From private research to a public product','Folder listings support names; the brief supports the intended engineering narrative.',body(entries.map(([time,title,files,desc])=>`<div class="timeline-item"><div class="time">${time}</div><div><h3>${title}</h3><p>${desc}</p><code>${files}</code></div></div>`).join('')),'<span>Windows modification times do not establish release order or prove implementation behavior.</span>');}
function about(){return heading('Built to make research inspectable.','Python Market Analytics Research Platform · Bara Mbaye')+panel('The project','A repeatable path from observations to evidence',body('<p class="big-statement">A result should survive scrutiny before it earns a place in a decision.</p><div class="prose"><p>This workstation turns a market-research workflow into an inspectable public product: structured observations, explicit assumptions, chronological evaluation, uncertainty and execution-aware interpretation.</p><p>The brief connects it to a broader KLEM research system. This build uses synthetic demonstration data until sanitized source outputs are imported.</p><p><strong>Product:</strong> Python Market Analytics Research Platform.<br><strong>Interface:</strong> MarketLab.<br><strong>Author:</strong> Bara Mbaye, University of Georgia mechanical engineering student.</p></div>'))+`<div class="grid-3">${[['Data engineering','Streaming ingestion, strict normalization, disk-backed deduplication and source fingerprints.'],['Research discipline','Chronological splits, purged labels, calibration uncertainty and temporal diagnostics.'],['Software & product','A modular Python compiler, responsive UI, reproducible tests and static deployment.']].map(([t,s])=>panel(t,'',body(`<p class="small muted">${s}</p>`))).join('')}</div>`+panel('Run it. Inspect it. Reproduce it.','No credentials or paid data service needed',body('<pre class="code-block">python -m marketlab build\npython -m unittest discover -s tests -v\npython -m http.server 8000 --directory dist</pre><p class="small muted">Open http://localhost:8000. The dist/index.html file also opens directly from disk.</p>'));}
const pages={overview,market,calibration,edge,validation,history,execution,failure,settlement,experiments:registry,architecture,methodology,timeline,about};
function render(){if(!D){$('#main').innerHTML='<div class="empty"><strong>Dataset unavailable</strong><p>Run python -m marketlab build to compile the public dataset.</p></div>';return;}$('#main').innerHTML=pages[state.page]();$('#breadcrumb').textContent=titles[state.page];document.title=titles[state.page]+' — MarketLab';document.querySelectorAll('.nav-item').forEach(a=>{const active=a.dataset.page===state.page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
function route(){const key=location.hash.slice(1);state.page=pages[key]?key:'overview';Object.assign(state,{pageIndex:0,query:'',period:'all',start:'',end:'',side:'all'});document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false');render();window.scrollTo(0,0);}
function download(name,content,type='text/plain'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
let timer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function showDetails(row){$('#detail-body').innerHTML=`<p class="eyebrow">${D.kind==='synthetic'?'Fictional':'Imported'} market observation</p><h2>${esc(row.ticker)}</h2><dl class="detail-grid">${Object.entries(row).map(([k,v])=>`<div><dt>${esc(k.replaceAll('_',' '))}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><div class="rule"></div><p class="small muted">Historical path unavailable: the public dataset contains one canonical observation per market. No intermediate quotes have been invented.</p>`;$('#detail').showModal();}
function saveExperiment(){const sample=rows(),record={id:'EXP-'+Date.now(),created_at:new Date().toISOString(),feature:state.feature,secondary:state.secondary,period:state.period,filters:{start:state.start,end:state.end,side:state.side},n:sample.length,status:'Exploratory',dataset_sha256:D.dataset_sha256,dataset_kind:D.kind,summary:A.summary(sample)};experiments.unshift(record);experiments=experiments.slice(0,100);try{localStorage.setItem('marketlab-experiments-v1',JSON.stringify(experiments));toast('Exploration saved in this browser.');}catch{toast('Saved in memory only. Export to keep it.');}if(state.page==='experiments')render();}
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();return;}const item=e.target.closest('[data-action],[data-detail],[data-experiment]');if(!item)return;if(item.dataset.detail){const row=D.rows.find(r=>r.ticker===item.dataset.detail);if(row)showDetails(row);return;}if(item.dataset.experiment!==undefined){const r=experiments[Number(item.dataset.experiment)];$('#detail-body').innerHTML=`<p class="eyebrow">Exploration snapshot</p><h2>${esc(r.id)}</h2><pre class="code-block">${esc(JSON.stringify(r,null,2))}</pre>`;$('#detail').showModal();return;}switch(item.dataset.action){case'reset':Object.assign(state,{period:'all',start:'',end:'',query:'',side:'all',pageIndex:0});render();break;case'prev':state.pageIndex--;render();break;case'next':state.pageIndex++;render();break;case'export':{const sample=rows(),keys=['ticker','timestamp','settlement_time','side','probability','outcome','ttx_minutes','atr','normalized_distance','momentum','session','weekday','period'];download('marketlab-'+D.kind+'-sample.csv',[keys.map(A.csvCell).join(','),...sample.map(r=>keys.map(k=>A.csvCell(r[k])).join(','))].join('\r\n'),'text/csv');toast('Exported '+sample.length+' '+D.kind+' observations.');break;}case'save-experiment':saveExperiment();break;case'export-experiments':download('marketlab-experiments.json',JSON.stringify(experiments,null,2),'application/json');break;case'clear-experiments':if(confirm('Clear saved explorations? Export first if you need a copy.')){experiments=[];try{localStorage.removeItem('marketlab-experiments-v1');}catch{}render();}break;}});
document.addEventListener('change',e=>{const key=e.target.dataset.state;if(key){state[key]=key==='bins'?Number(e.target.value):e.target.value;state.pageIndex=0;render();}});
document.addEventListener('input',e=>{if(e.target.dataset.state==='query'){const value=e.target.value,position=e.target.selectionStart;state.query=value;state.pageIndex=0;render();const input=$('#query');input.focus();input.setSelectionRange(position,position);return;}const key=e.target.dataset.scenario;if(key){state[key]=Number(e.target.value);$('#'+key+'-value').textContent=state[key]+(key==='fill'?'%':'¢');$('#scenario-results').innerHTML=executionResults(A.execution(rows(),state.fee,state.slippage,state.fill/100));}});
$('#menu').addEventListener('click',()=>{const open=document.body.classList.toggle('menu-open');$('#menu').setAttribute('aria-expanded',String(open));});$('.dialog-close').addEventListener('click',()=>$('#detail').close());
const icon='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 4h6v6H4z M14 4h6v6h-6z M4 14h6v6H4z M14 14h6v6h-6z"/></svg>';
$('#navigation').innerHTML=nav.map(([label,items])=>`<div class="nav-heading">${label.toUpperCase()}</div>${items.map(([id,title])=>`<a class="nav-item" data-page="${id}" href="#${id}">${['overview','about'].includes(id)?icon:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 3v18h18 M7 16l4-6 4 3 5-7"/></svg>'}<span>${title}</span></a>`).join('')}`).join('');
if(D)$('#mode').textContent=D.kind==='synthetic'?'Synthetic demo':'Imported sample';window.addEventListener('hashchange',route);route();

document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false');}});
